import{_ as d,a as l}from"./chunks/remote-storage.BYATIY0S.js";import{_ as i,C as s,o as n,c,a2 as e,j as r,a as o,E as g}from"./chunks/framework.Dx-TCpNt.js";const x=JSON.parse('{"title":"远端存储与备份","description":"图片可以放在另一块磁盘、NAS 共享或 WebDAV 服务器上，而标注仍保存在本地 data/ 目录。本页说明远端图库的行为、网络闹脾气时会发生什么，以及备份如何工作。","frontmatter":{"description":"图片可以放在另一块磁盘、NAS 共享或 WebDAV 服务器上，而标注仍保存在本地 data/ 目录。本页说明远端图库的行为、网络闹脾气时会发生什么，以及备份如何工作。"},"headers":[],"relativePath":"zh/guide/remote.md","filePath":"zh/guide/remote.md","lastUpdated":1794780892000}'),h={name:"zh/guide/remote.md"};function p(b,t,u,m,_,f){const a=s("Badge");return n(),c("div",null,[t[4]||(t[4]=e('<h1 id="远端存储与备份" tabindex="-1">远端存储与备份 <a class="header-anchor" href="#远端存储与备份" aria-label="Permalink to &quot;远端存储与备份&quot;">​</a></h1><p>图片可以放在另一块磁盘、NAS 共享或 WebDAV 服务器上，而标注仍保存在本地 <code>data/</code> 目录。本页说明远端图库的行为、网络闹脾气时会发生什么，以及备份如何工作。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>漫画库往往比你愿意让应用索引的磁盘大得多，或者本来就在 NAS 上。把几万张图片复制进 <code>raw/</code> 很浪费。反过来，标注体积很小，绝不能因为 Wi-Fi 眨了下眼就消失。</p><p>KomaYomi 把两者分开：<strong>图片按需从远端读取，标注写入本地。</strong></p><h2 id="配置远端图库" tabindex="-1">配置远端图库 <a class="header-anchor" href="#配置远端图库" aria-label="Permalink to &quot;配置远端图库&quot;">​</a></h2><ol><li>打开侧栏的 <strong>备份 / 恢复</strong>。</li><li>在 <strong>远端素材 / 网络存储</strong> 中点击 <strong>添加远端目录</strong>。</li><li>填写目标：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>对话框中显示的标签。</td></tr><tr><td><strong>类型</strong></td><td>本机目录、网络盘 / UNC，或 WebDAV。</td></tr><tr><td><strong>目录路径</strong></td><td>例如 <code>D:\\manga</code> 或 <code>\\\\nas\\share\\manga</code>（本机 / 网络）。</td></tr><tr><td><strong>WebDAV 地址</strong>、<strong>用户名</strong>、<strong>密码</strong></td><td>WebDAV 凭据。</td></tr><tr><td><strong>只读</strong></td><td>把来源标记为只读，应用永远不会写入它。</td></tr></tbody></table><ol start="4"><li>点击 <strong>测试连接</strong>。对话框会显示<em>在线</em> / <em>离线</em>，以及目标是否只读。</li><li>点击 <strong>同步远端目录树</strong>。</li></ol><h3 id="同步做了什么" tabindex="-1">同步做了什么 <a class="header-anchor" href="#同步做了什么" aria-label="Permalink to &quot;同步做了什么&quot;">​</a></h3><p>应用遍历远端文件夹，在本地镜像（<code>data/cache/remote/tree/</code>）中创建<strong>零字节占位文件</strong>。之后图库扫描器和目录规则照常在这个镜像上运行，因此远端卷会像本地卷一样出现在侧栏，分组同样是 卷 → 语言 → 话。</p><ul><li>只镜像图片扩展名：<code>.jpg</code>、<code>.jpeg</code>、<code>.png</code>、<code>.webp</code>、<code>.gif</code>、<code>.avif</code>、<code>.bmp</code>。</li><li>遍历深度限制为 10 层，文件上限 <strong>20,000 个</strong>；触及上限时会提示“已达文件上限”并停止。</li><li>无法读取的文件夹会被计数并报告，但不会中断同步。</li><li>再次同步会替换镜像；标注不受影响。</li></ul><h2 id="按需加载与缓存" tabindex="-1">按需加载与缓存 <a class="header-anchor" href="#按需加载与缓存" aria-label="Permalink to &quot;按需加载与缓存&quot;">​</a></h2><p>打开页面时：</p><ol><li>应用检查本地缓存中是否有原图。</li><li>如果缺失，就从远端来源拉取。</li><li>字节写入 <code>data/cache/remote/files/</code>，按提供方和路径做内容寻址。</li><li>缩略图由缓存的原图生成。</li></ol><p>没有“下载整个图库”的步骤。只有你真正打开的页面才会被拉取。</p><table tabindex="0"><thead><tr><th>控件</th><th>含义</th></tr></thead><tbody><tr><td><strong>缓存 n MB / 上限 MB（n 个文件）</strong></td><td>当前缓存用量。</td></tr><tr><td><strong>缓存上限（MB）</strong></td><td>上限；默认 <strong>512 MB</strong>，可取任意正值，最大 100,000。</td></tr><tr><td><strong>清除图片缓存</strong></td><td>删除缓存的远端原图和缩略图；可安全使用，之后会重新拉取。</td></tr></tbody></table><p>缓存超过上限时，会按最近最少使用淘汰文件，直到用量降到上限的 <strong>90%</strong> 以下。</p><h2 id="离线行为" tabindex="-1">离线行为 <a class="header-anchor" href="#离线行为" aria-label="Permalink to &quot;离线行为&quot;">​</a></h2><p>网络断了会怎样：</p><table tabindex="0"><thead><tr><th>情况</th><th>结果</th></tr></thead><tbody><tr><td>页面已缓存</td><td>离线也能正常打开。</td></tr><tr><td>页面未缓存，远端离线</td><td>图片请求失败，返回 HTTP <strong>503</strong> <code>ERR_REMOTE_UNAVAILABLE</code>；界面显示错误而不是卡住。</td></tr><tr><td>未缓存页面的缩略图，远端离线</td><td>HTTP <strong>502</strong> <code>ERR_THUMB_FETCH_FAILED</code>。</td></tr><tr><td>标注、笔记、分格</td><td>始终在本地；图片已缓存的页面可以继续编辑。</td></tr></tbody></table><p>如果保存失败——浏览器离线、服务端正在重启，或返回 5xx——页面文档不会丢，而是进入浏览器存储里的本地 <strong>outbox</strong>（待写队列），之后再补写：</p><ul><li>每页一条记录；同一页的新写入会替换旧记录，因此重放可以安全重复。</li><li>上限 100 页。浏览器存储写满时，会先丢弃粘贴的截图，保证笔记文字存活。</li><li>重放会在页面加载时、浏览器恢复联网时、仍有待写内容时每 30 秒，以及从待写计数按钮手动触发。</li><li>遇到第一个失败就停下，以保证版本历史的顺序，稍后再试。</li></ul><p>这是浏览器侧的缓冲，不是远端同步：每次写入最终仍落到本地 <code>data/</code> 目录。</p><div class="tip custom-block"><p class="custom-block-title">实用的离线用法</p><p>离线前先打开你打算学习的页面。原图和缩略图已缓存，它们会保持可读。缓存上限决定你能随身带多少。</p></div><h2 id="密码与凭据" tabindex="-1">密码与凭据 <a class="header-anchor" href="#密码与凭据" aria-label="Permalink to &quot;密码与凭据&quot;">​</a></h2><ul><li>密码<strong>不会</strong>存储在 <code>storage.json</code> 中。</li><li>它们以 <strong>AES-256-GCM</strong> 加密到 <code>data/secrets.json.enc</code>，使用按安装生成的密钥文件 <code>data/.secret.key</code>，权限模式为 <code>0600</code>。</li><li>因此复制或同步 <code>data/</code> 文件夹不会泄露密码，界面也从不回显密码——密码字段留空即可保留已保存的值。</li><li>密码<strong>不包含在备份中</strong>。</li></ul><h2 id="备份目标" tabindex="-1">备份目标 <a class="header-anchor" href="#备份目标" aria-label="Permalink to &quot;备份目标&quot;">​</a></h2><p>同一个对话框会列出 <strong>备份目标</strong>。目标是备份 ZIP 上传的位置：</p><ol><li><strong>添加备份目标</strong>，选择本机目录、网络盘或 WebDAV。</li><li><strong>备份到此目标</strong> 会把 <code>data/</code> 打成 ZIP，上传到该目标下的 <code>backups/backup-&lt;timestamp&gt;.zip</code>。</li><li>完成后会显示目标、文件名和大小。</li></ol><p>任何已配置的来源或目标都可以用 <strong>测试连接</strong> 测试；离线的会被报告出来。</p><h2 id="手动备份与恢复" tabindex="-1">手动备份与恢复 <a class="header-anchor" href="#手动备份与恢复" aria-label="Permalink to &quot;手动备份与恢复&quot;">​</a></h2><figure class="shot"><img src="'+d+'" alt="备份与恢复对话框：生成备份、选择备份文件以及检查后的归档摘要"><figcaption>备份对话框。恢复前会先检查备份，因此在覆盖任何内容之前，就能看到它包含多少页、笔记和模板。</figcaption></figure><ul><li><strong>生成并下载备份</strong> 会生成 <code>data/</code> 的 ZIP：页面、模板、预设、版式、<code>library.json</code> 和 <code>.backup-meta.json</code>。缩略图缓存和临时文件不包含在内。</li><li><strong>选择备份文件…</strong> 会先检查 ZIP，报告其中包含多少页、笔记、模板和预设，以及涉及哪些卷。</li><li>恢复会<strong>覆盖 <code>data/</code> 下的同名文件</strong>，但不会删除备份中没有的页面。恢复前会先写入当前数据的快照。</li></ul><p>文件级约定和确切的存储 JSON 见<a href="/KomaYomi-docs/zh/remote-backup">远端存储与备份（参考）</a>。</p><h2 id="当前限制" tabindex="-1">当前限制 <a class="header-anchor" href="#当前限制" aria-label="Permalink to &quot;当前限制&quot;">​</a></h2>',36)),r("p",null,[t[0]||(t[0]=o("以下功能",-1)),t[1]||(t[1]=r("strong",null,"尚未实现",-1)),t[2]||(t[2]=o("，仍标记为 ",-1)),g(a,{type:"warning",text:"计划中"}),t[3]||(t[3]=o("：",-1))]),t[5]||(t[5]=e('<ul><li>定时或自动备份：备份需手动启动。</li><li>WebDAV 以外的云服务（不支持 Dropbox / Google Drive / S3）。</li></ul><figure class="shot"><img src="'+l+'" alt="备份 / 恢复对话框中的远端存储：WebDAV 来源、缓存用量与一个备份目标"><figcaption>“备份 / 恢复”中的远端存储：WebDAV 来源、缓存用量与备份目标。</figcaption></figure><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>远端卷没有出现。</strong> 运行 <strong>同步远端目录树</strong>；图库扫描的是镜像。检查结果中的文件上限和跳过文件夹数量。</li><li><strong>每一页都返回 503。</strong> 远端离线，且该页从未缓存。重新联网后再次打开页面。</li><li><strong>磁盘占用持续增长。</strong> 缓存上限默认 512 MB；确有需要再调高，或在切换图库时清除缓存。</li><li><strong>备份里没有密码。</strong> 这是有意设计；在另一台机器恢复后重新输入密码。</li><li><strong>网络路径在资源管理器里能用，这里不行。</strong> 网络盘必须对运行应用的账户可见——应用跑在服务账户或另一个桌面用户下时，尤其容易踩到。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/remote-backup">备份参考</a> —— 存储 JSON 与文件级细节。</li><li><a href="/KomaYomi-docs/zh/guide/gallery">图库与导入</a> —— 目录规则同样作用于镜像。</li><li><a href="/KomaYomi-docs/server/error-codes">服务与 CLI 消息码</a> —— <code>ERR_REMOTE_UNAVAILABLE</code>、<code>ERR_THUMB_FETCH_FAILED</code>。</li></ul>',6))])}const P=i(h,[["render",p]]);export{x as __pageData,P as default};
